import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>文字能把一张图片变成一条信息。说明文字解释照片内容，标题给它起名字，引用给它一个声音。</p>\n<p>给图片加文字是个简单的技能，用途却很多：社交帖子、表情包、演示文稿、产品标签和带标注的截图都离不开它。</p>\n<p>这篇指南会讲清怎么把文字加好。包括字体、大小、颜色、对比度、描边、位置，以及那些让文字读不出来的错误。</p>\n<h2 id=\"what-text-on-image-does\">图片上的文字是干什么的</h2>\n<p>文字补充了图片本身表达不了的意思。一张山的照片只是一座山，加上说明文字就变成一段回忆、一个笑话或一份邀请。</p>\n<p>文字还提供上下文。写在图片上的日期、地点或名字，不用额外解释就能告诉观众他们在看什么。</p>\n<p>对商家来说，图片上的文字就是标签。带价格的产品照片、带折扣的促销横幅、带活动日期的海报，都靠文字来销售。</p>\n<p>关键是克制。几句放得恰到好处的文字能强化图片，一段塞满照片的文字反而会遮住它本来要表达的东西。</p>\n<h2 id=\"captions-vs-watermarks\">说明文字、标题和水印是不同的工作</h2>\n<p>说明文字解释图片。它放在主体附近，容易读，是给每个看照片的人看的。</p>\n<p>标题给图片起名字。它通常比说明文字更大更粗，为页面或帖子里的其他内容定下基调。</p>\n<p>水印保护图片。它表明归属，常常是半透明的，目的是在复制和转发后还能留下来。</p>\n<p>不要把三者搞混。看着像水印的说明文字会被忽略，看着像说明文字的水印起不到任何保护作用。</p>\n<h2 id=\"fonts-explained\">字体：选一种合得来的字形</h2>\n<p>字体在别人读到文字之前，就先定下了文字的氛围。粗无衬线字体感觉现代直接，衬线字体感觉经典正式。</p>\n<p>选一种和图片合得来的字体。俏皮的表情包需要粗壮有力的字体，婚礼照片需要优雅轻盈的字体。</p>\n<p>一张图片最多用一到两种字体。混用太多字形看着混乱，单一一致的字体让设计保持干净专业。</p>\n<p>按实际使用的尺寸检查字体。装饰字体放大了看着漂亮，缩到小尺寸可能读不出来。</p>\n<h2 id=\"text-size-scaling\">文字大小：小图与大图</h2>\n<p>文字大小是按图片百分比设置的，从2%到22%。同样的设置，在小缩略图和大尺寸相机照片上看起来都一致。</p>\n<p>按像素设置大小的话，大照片上合适的尺寸，到了小图上可能看不见。百分比设置彻底避免了这个问题。</p>\n<p>标题用接近范围上限的大尺寸，说明文字或署名用小一点、但依然可读的尺寸。</p>\n<p>按实际分享的尺寸检查文字。全尺寸看着粗壮的标题，在社交信息流预览里可能很小；按缩略图调好的说明文字，印大了可能占主导。</p>\n<h2 id=\"colour-and-contrast\">颜色与对比度：让文字可读</h2>\n<p>白色文字适合深色背景，黑色文字适合浅色背景，但大多数照片两种背景都有。一种颜色总会在图片的某个地方消失。</p>\n<p>让文字可读的是对比度，不只是颜色本身。亮色文字放在明亮背景上失败，深色文字放在深色背景上同样失败。</p>\n<p>把文字放在照片最平坦的部分。晴朗天空或空白墙面上的说明文字，比人群或森林上的说明文字容易读得多。</p>\n<p>没有平坦区域时，加一块背景板。白色文字后面放半透明的深色框，任何地方都可读，只不过遮住的图片面积更大了。</p>\n<h2 id=\"outline-and-shadow\">描边与阴影</h2>\n<p>描边是在每个字母周围画一圈边框。白色文字加细细的深色描边，在明亮天空上也能读，这就是表情包用它的原因。</p>\n<p>阴影把文字从背景上托起来。它在字母后面加一道柔和的深色边缘，帮助文字脱颖而出，又没有描边那么硬。</p>\n<p>两者选其一，不要同时开到最强。描边加浓重阴影会让文字看着杂乱，单一效果更干净。</p>\n<p>经典表情包文字用白色字母加粗深色描边。这种组合在几乎任何背景上都可读，所以成了标准做法。</p>\n<h2 id=\"positioning-and-layers\">位置与图层</h2>\n<p>文字图层可以移到图片上的任何位置。拖动图层就能放置，有多个图层时可以逐个选中。</p>\n<p>顶部和底部是说明文字的经典位置。顶部是标题、底部是笑点，这就是表情包的格式，符合自上而下的阅读习惯，所以好用。</p>\n<p>文字远离边缘。贴着边框的说明文字看着局促，平台还会为不同屏幕尺寸再次裁剪边缘。</p>\n<p>有多个图层时，修改之前先选中想改的那一层。改错图层是常见错误，检查一下当前选中的是哪一层就能避免。</p>\n<h2 id=\"rotating-text\">旋转文字，制造效果</h2>\n<p>文字可以按自定义角度倾斜，给设计增加活力。略微倾斜的标题感觉灵动，端正的文字感觉平静正式。</p>\n<p>旋转要克制。倾斜几度能增加个性，角度太陡会让文字难读，看着像失误。</p>\n<p>斜文字适合海报和社交图片，设计就是要抓眼球。说明文字和标签则需要清晰，斜文字不合适。</p>\n<p>按实际查看的尺寸检查旋转后的文字。全尺寸看着好的倾斜，在信息流预览里可能让小字读不出来。</p>\n<h2 id=\"multi-line-text\">多行说明文字</h2>\n<p>在文字内容里按回车可以换行。这样不用为每一行单独建图层，就能写出两三行的说明文字。</p>\n<p>每行保持简短。横贯整张图片的说明文字很难读，居中在主体上的短行更容易看。</p>\n<p>在句子自然停顿的地方换行。短语中间换行感觉别扭，短语之间换行感觉是特意的。</p>\n<p>表情包顶部一行、底部一行，用两个图层分开。分开的图层可以把每行精确放到属于它的位置。</p>\n<h2 id=\"memes\">做表情包</h2>\n<p>表情包就是一张照片加一句简短有趣的说明文字，通常是顶部和底部带粗深色描边的白色文字。格式很简单，简单正是它的意义所在。</p>\n<p>文字保持简短。带一段文字的表情包不好笑，因为没人会在笑话图片上读段落。顶部一行、底部一行就够了。</p>\n<p>用粗壮有力的字体。经典表情包用的是粗无衬线字体，小尺寸和复杂背景上依然可读。</p>\n<p>先放顶部一行，再放底部一行。眼睛先读顶部的铺垫，再看图片，最后读底部的笑点。</p>\n<h2 id=\"quotes-and-titles\">引用、标题与社交图片</h2>\n<p>照片上的引用是很流行的社交格式。文字通常很大、居中，放在图片的平坦区域或加深的背景上。</p>\n<p>引用保持简短。一句话的效果远胜一段话，因为图片和文字共享空间，谁也不该占主导。</p>\n<p>标题比说明文字用更大的尺寸、更粗的字体。标题应该是眼睛最先找到的东西，图片是支持它的，而不是和它竞争。</p>\n<p>照片太复杂时，在文字后面把图片稍微调暗。半透明的覆盖层能让白色文字可读，又不完全遮住照片。</p>\n<h2 id=\"annotations\">标注与标签</h2>\n<p>标注解释图片的各个部分。带箭头的标签、编号步骤或简短说明，能把截图变成操作指南。</p>\n<p>标注保持简短，放在它描述的东西附近。离主体太远的标签会让观众困惑，紧挨着的标签一目了然。</p>\n<p>一张图片上的所有标注用统一风格。同样的字体、大小和颜色，让图片看着专业、容易看懂。</p>\n<p>截图先裁剪再用<a href=\"/zh/tupian-tianjia-wenzi/\">图片加文字工具</a>标注。裁紧的图片加几处清晰的标签，比没有任何指引的整张截图有用得多。</p>\n<h2 id=\"formats-and-export\">格式与导出</h2>\n<p>工具支持常见的图片格式，包括JPG、PNG、WebP和HEIC，文件最大20MB。导出可选JPG、PNG或WebP，按需要选择。</p>\n<p>导出PNG或WebP能保留底图的透明度。如果来源是透明PNG贴纸，文字导出后透明区域依然透明。</p>\n<p>带文字的照片用高画质JPG导出效果很好。JPG压缩会让文字边缘略微变软，小说明文字要保持高画质。</p>\n<p>JPG和WebP导出时会出现画质滑杆，PNG导出时没有，因为PNG是无损的，没有画质可调。</p>\n<h2 id=\"privacy-local-processing\">隐私：不上传也能加文字</h2>\n<p>所有文字编辑都在浏览器里完成。照片不会上传到服务器，这对个人照片、家庭照片或工作截图来说很重要。</p>\n<p>这比云端编辑器实在得多。加了说明文字的家庭照片，没必要为了加几个字就传到看不见的服务器上。</p>\n<p>工具导出时还会清除EXIF GPS数据。下载下来的带文字照片，不再带有拍摄地点的记录。</p>\n<p>留好没有文字的原照片。文字一旦压进导出文件就去不掉了，原文件是唯一的干净副本。</p>\n<h2 id=\"common-mistakes\">加文字时最容易犯的错</h2>\n<p>最常见的错误是文字太小。全尺寸看着好的说明文字，在社交信息流里图片显示小得多，可能读不出来。</p>\n<p>另一个错误是对比度差。明亮天空上的白色文字和深色背景上的黑色文字都会消失，所以要在实际照片上检查文字，不要在空白画布上检查。</p>\n<p>很多人还会写太多。一段文字盖在照片上会遮住图片、压倒观众，几句选得好的词效果更好。</p>\n<p>最后，不要把文字放在平台会裁掉的位置。社交应用会为不同屏幕修剪图片边缘，重要的词要放在框内足够靠里的位置。</p>\n<h2 id=\"text-on-product-photos\">产品照片上的文字</h2>\n<p>产品照片常常带有简短文字：价格、折扣或特点。文字要大、要粗，放在不遮住产品本身的位置。</p>\n<p>价格或优惠放在角落，不要横穿中间。角落标签让产品保持可见，中央标签会遮住你正在卖的东西。</p>\n<p>整个目录用统一风格。同样的字体、大小和颜色，价格标签在每张图上都一样，店铺看着专业、可信。</p>\n<p>文字保持简短。价格加一个词，比如“特价”或“新品”，就够了。产品照片上的一段话会分散买家对产品的注意力。</p>\n<p>分步骤的操作见<a href=\"/zh/blog/ruhe-zai-tupian-shang-jia-wenzi/\">如何在图片上加文字</a>。可读性规则读<a href=\"/zh/blog/tupian-wenzi-qingxi-kedu-jiqiao/\">图片文字：字体、对比度与可读性</a>；想标记归属而不是加说明文字，可以用<a href=\"/zh/tianjia-shuiyin/\">图片水印工具</a>。</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"照片上的文字用什么字体最好？","answer":"大多数照片用粗无衬线字体最稳妥，小尺寸和复杂背景上依然可读。衬线字体适合婚礼照片这类正式图片，装饰字体只适合大尺寸。每张图片最多用一到两种字体。"},{"question":"明亮照片上的白色文字怎么变可读？","answer":"给字母加深色描边或阴影，在明亮区域也能保持可见。把文字放在照片最暗的部分也有帮助。没有平坦区域时，文字后面加半透明的深色底框。"},{"question":"一张图片能加多行文字吗？","answer":"能。在文字内容里按回车可以在同一图层里换行，也可以为每行单独加图层。分开的图层可以独立定位顶部和底部说明文字，这就是经典的表情包布局。"},{"question":"加文字和加水印有什么区别？","answer":"加文字是做说明、标题或标注，给每个人看的；加水印是加半透明的归属标记，目的是在复制后还能留下来。写信息用文字工具，要保护用加水印工具。"},{"question":"社交媒体图片上的文字要多大？","answer":"大到在小信息流预览里也能读，不只是全尺寸下可读。标题要用2%到22%范围里接近上限的尺寸，说明文字可以小一点。导出后按信息流里的实际尺寸看一眼再发布。"},{"question":"给照片加文字会清除位置信息吗？","answer":"会。用工具导出时，文件里的EXIF GPS标签会被清除。文字压进图片，位置记录在同一步被删除。想保留这些数据的话，留好原文件。"}];
